-- Fix admin approval: auth.users.confirmed_at is generated by Supabase.
-- Only email_confirmed_at is writable; confirmed_at is derived automatically.

create or replace function public.admin_set_user_access(
  p_user_id uuid,
  p_role text,
  p_status text
)
returns void
language plpgsql
security definer
set search_path = ''
as $function$
declare
  v_email text;
begin
  if not private.is_admin() then
    raise exception 'Administrator permission required';
  end if;

  if p_role not in ('ADMIN','LECTURER','REVIEWER','REGISTRAR','STUDENT') then
    raise exception 'Invalid role';
  end if;

  if p_status not in ('PENDING','ACTIVE','SUSPENDED') then
    raise exception 'Invalid account status';
  end if;

  select lower(btrim(institutional_email))
  into v_email
  from public.profiles
  where id = p_user_id;

  if not found then
    raise exception 'User profile not found';
  end if;

  -- email_confirmed_at is the writable source column. Supabase derives
  -- auth.users.confirmed_at automatically because it is a generated column.
  if p_status = 'ACTIVE' then
    update auth.users
    set email_confirmed_at = coalesce(email_confirmed_at, now())
    where id = p_user_id
      and email_confirmed_at is null;
  end if;

  update public.profiles
  set role = p_role,
      account_status = p_status,
      email_verified = (email_verified or p_status = 'ACTIVE'),
      updated_at = now()
  where id = p_user_id;

  insert into public.audit_logs(actor_id, action, entity_type, entity_id, details)
  values (
    (select auth.uid()),
    'USER_ACCESS_UPDATED',
    'profile',
    p_user_id::text,
    jsonb_build_object(
      'role', p_role,
      'status', p_status,
      'email_verified', (p_status = 'ACTIVE'),
      'email_domain', split_part(coalesce(v_email, ''), '@', 2)
    )
  );
end;
$function$;

revoke all on function public.admin_set_user_access(uuid, text, text) from public, anon;
grant execute on function public.admin_set_user_access(uuid, text, text) to authenticated;
